<template>
  <div class="page-container sil-page"><div class="page-head"><div><h2>青贮生产/收储台账</h2><p>汇总计划、实际种植及收储进度，包含受灾补充收储台账。</p></div></div><div class="stat-grid"><div><span>计划面积</span><b>{{ sum('planArea').toFixed(1) }}</b><em>亩</em></div><div><span>实际面积</span><b>{{ sum('actualArea').toFixed(1) }}</b><em>亩</em></div><div><span>预计产量</span><b>{{ sum('expectedYield').toFixed(1) }}</b><em>吨</em></div><div><span>实际产量</span><b>{{ sum('actualYield').toFixed(1) }}</b><em>吨</em></div></div><div class="panel"><el-form :inline="true" class="filters"><el-form-item label="年份"><el-select v-model="filters.year" clearable placeholder="全部" style="width:120px"><el-option :value="2026" label="2026年"/><el-option :value="2027" label="2027年"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="filters.status" clearable placeholder="全部" style="width:130px"><el-option label="已完成" value="已完成"/><el-option label="收储中" value="收储中"/></el-select></el-form-item><el-form-item label="关键词"><el-input v-model="filters.keyword" clearable placeholder="主体、备案编号或买方"/></el-form-item><el-button type="primary" @click="apply">查询</el-button><el-button @click="reset">重置</el-button></el-form><el-table :data="rows" stripe border><el-table-column prop="isSupplement" label="台账类型" width="100"><template #default="{row}"><el-tag size="small" :type="row.isSupplement ? 'warning' : 'success'">{{ row.isSupplement ? '补充收储' : '生产收储' }}</el-tag></template></el-table-column><el-table-column prop="filedNo" label="备案编号" width="180"/><el-table-column prop="subjectName" label="收储主体" min-width="180"/><el-table-column prop="plotText" label="地块" min-width="130" show-overflow-tooltip/><el-table-column prop="planArea" label="计划面积（亩）" width="125" align="right"/><el-table-column prop="actualArea" label="实际面积（亩）" width="120" align="right"/><el-table-column prop="expectedYield" label="预计产量（吨）" width="125" align="right"/><el-table-column prop="actualYield" label="实际产量（吨）" width="120" align="right"><template #default="{row}">{{ row.actualYield ?? '—' }}</template></el-table-column><el-table-column prop="price" label="价格（元/吨）" width="120" align="right"/><el-table-column prop="buyer" label="买方/去向" min-width="170" show-overflow-tooltip/><el-table-column prop="harvestTime" label="收储时间" width="125"/><el-table-column prop="status" label="状态" width="95"><template #default="{row}"><el-tag size="small" :type="row.status === '已完成' ? 'success' : 'warning'">{{ row.status }}</el-tag></template></el-table-column><el-table-column label="操作" width="90" fixed="right"><template #default="{row}"><el-button link type="primary" @click="showDetail(row)">详情</el-button></template></el-table-column></el-table><el-empty v-if="!rows.length" description="暂无台账数据"/></div><el-dialog v-model="visible" title="生产/收储台账详情" width="760px"><template v-if="current"><el-descriptions :column="3" border><el-descriptions-item label="台账类型">{{ current.isSupplement ? '受灾补充收储' : '生产收储' }}</el-descriptions-item><el-descriptions-item label="备案编号">{{ current.filedNo }}</el-descriptions-item><el-descriptions-item label="年度">{{ current.year }}年</el-descriptions-item><el-descriptions-item label="收储主体">{{ current.subjectName }}</el-descriptions-item><el-descriptions-item label="地块位置">{{ current.plotText || '备案地块' }}</el-descriptions-item><el-descriptions-item label="收储状态">{{ current.status }}</el-descriptions-item><el-descriptions-item label="计划面积">{{ current.planArea }} 亩</el-descriptions-item><el-descriptions-item label="实际面积">{{ current.actualArea }} 亩</el-descriptions-item><el-descriptions-item label="预计产量">{{ current.expectedYield }} 吨</el-descriptions-item><el-descriptions-item label="实际产量">{{ current.actualYield ?? '—' }} 吨</el-descriptions-item><el-descriptions-item label="价格">{{ current.price }} 元/吨</el-descriptions-item><el-descriptions-item label="买方/去向">{{ current.buyer || '—' }}</el-descriptions-item><el-descriptions-item label="收储时间" :span="3">{{ current.harvestTime || '—' }}</el-descriptions-item></el-descriptions></template></el-dialog></div>
</template>
<script setup>
import { onMounted, reactive, ref } from 'vue'
import { fetchLedgers } from '@/api/sil'
import { useUserStore } from '@/stores/user'
const userStore = useUserStore(); const rows = ref([]); const allRows = ref([]); const current = ref(null); const visible = ref(false); const filters = reactive({ year: '', status: '', keyword: '' }); const sum = (key) => rows.value.reduce((total, row) => total + Number(row[key] || 0), 0); const apply = () => { rows.value = allRows.value.filter((r) => (!filters.year || r.year === filters.year) && (!filters.status || r.status === filters.status) && (!filters.keyword || `${r.filedNo}${r.subjectName}${r.buyer || ''}`.includes(filters.keyword))) }; const reset = () => { Object.assign(filters, { year: '', status: '', keyword: '' }); apply() }; const showDetail = (row) => { current.value = row; visible.value = true }; const load = async () => { allRows.value = await fetchLedgers(userStore.role); allRows.value = allRows.value.map((r) => ({ ...r, plotText: r.isSupplement ? '受灾补充地块' : '备案种植地块' })); apply() }; onMounted(load)
</script>
<style scoped lang="scss">.sil-page{overflow:auto}.page-head{margin-bottom:14px}.page-head h2{margin:4px 0;color:var(--ah-text);font-size:22px}.page-head p{color:var(--ah-text-secondary);font-size:13px}.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:14px}.stat-grid>div{padding:16px 20px;background:#fff;border:1px solid #e6edf5;border-radius:8px}.stat-grid span{display:block;color:#7b8794;font-size:13px}.stat-grid b{display:inline-block;margin-top:8px;color:var(--ah-primary);font-size:25px}.stat-grid em{margin-left:6px;font-style:normal;color:#8492a6;font-size:12px}.filters{display:flex;align-items:center;flex-wrap:wrap}.filters :deep(.el-form-item){margin-bottom:12px}@media(max-width:1000px){.stat-grid{grid-template-columns:repeat(2,1fr)}}</style>